--
-- Name: check_feature_pipeline_freshness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_feature_pipeline_freshness() RETURNS TABLE(symbol text, tf text, last_ts timestamp with time zone, gap_minutes double precision)
    LANGUAGE sql
    AS $$
    SELECT symbol, tf, MAX(ts) as last_ts,
           EXTRACT(EPOCH FROM (NOW() - MAX(ts))) / 60.0 as gap_minutes
    FROM intelligence_features
    WHERE ts > NOW() - INTERVAL '30 minutes'
    GROUP BY symbol, tf
    HAVING MAX(ts) < NOW() - INTERVAL '10 minutes'
    ORDER BY gap_minutes DESC;
$$;


--
-- Name: classification_node_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classification_node_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    today date;
    parent_path text[];
BEGIN
    IF TG_OP = 'INSERT' THEN
        today := classification_write_date();
        IF NEW.valid_from <> today THEN
            RAISE EXCEPTION 'classification_node %.%: valid_from must be today % (got %)',
                NEW.scheme, NEW.code, today, NEW.valid_from;
        END IF;
        IF NEW.parent_code IS NULL THEN
            IF NEW.path IS DISTINCT FROM ARRAY[NEW.code] THEN
                RAISE EXCEPTION 'classification_node %.%: a root path must be {%}', NEW.scheme, NEW.code, NEW.code;
            END IF;
        ELSE
            SELECT path INTO parent_path FROM classification_node
            WHERE scheme = NEW.scheme AND code = NEW.parent_code;
            IF NEW.path IS DISTINCT FROM parent_path || NEW.code THEN
                RAISE EXCEPTION 'classification_node %.%: path % does not extend parent % path %',
                    NEW.scheme, NEW.code, NEW.path, NEW.parent_code, parent_path;
            END IF;
        END IF;
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        IF (NEW.scheme, NEW.code, NEW.parent_code, NEW.level, NEW.path, NEW.valid_from)
           IS DISTINCT FROM
           (OLD.scheme, OLD.code, OLD.parent_code, OLD.level, OLD.path, OLD.valid_from) THEN
            RAISE EXCEPTION 'classification_node %.%: identity columns are immutable; a reparent mints a new code (D-01)',
                OLD.scheme, OLD.code;
        END IF;
        IF NEW.valid_to IS DISTINCT FROM OLD.valid_to THEN
            today := classification_write_date();
            IF OLD.valid_to IS NOT NULL OR NEW.valid_to IS DISTINCT FROM today THEN
                RAISE EXCEPTION 'classification_node %.%: valid_to may only be set once, to today %',
                    OLD.scheme, OLD.code, today;
            END IF;
        END IF;
        RETURN NEW;
    ELSE
        RAISE EXCEPTION 'classification_node is append-only: % is not allowed', TG_OP;
    END IF;
END $$;


--
-- Name: classification_write_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classification_write_date() RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    txn_day date := (now() AT TIME ZONE 'UTC')::date;
    wall_day date := (clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
    IF txn_day <> wall_day THEN
        RAISE EXCEPTION 'classification write refused: transaction started on % (UTC) but it is now %; rerun in a fresh transaction',
            txn_day, wall_day;
    END IF;
    RETURN txn_day;
END $$;


--
-- Name: fn_cascade_concept_parent_deprecation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_cascade_concept_parent_deprecation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'deprecated' AND OLD.status <> 'deprecated' THEN
        -- BUG-1 fix (vs. feature_registry original and todo 118's literal translation): log
        -- the audit row BEFORE the UPDATE runs. Logging after would find every cascaded child
        -- already 'deprecated', so a WHERE cr.status <> 'deprecated' filter at that point
        -- selects zero rows and the cascade goes silently unaudited.
        INSERT INTO concept_transition_log
            (concept_id, domain, name, from_status, to_status, trigger_reason, triggered_at, notes)
        SELECT cr.concept_id, cr.domain, cr.name, cr.status, 'deprecated', 'parent_cascade', NOW(),
               'Cascaded from parent concept ' || NEW.name || ' (domain ' || NEW.domain || ')'
        FROM concept_registry cr
        JOIN concept_parent cp ON cp.child_concept_id = cr.concept_id
        WHERE cp.parent_concept_id = NEW.concept_id AND cr.status <> 'deprecated';

        -- BUG-2 fix: from_status above is the child's REAL current status (cr.status), never
        -- the hard-coded 'active' both prior versions used.
        UPDATE concept_registry
        SET status = 'deprecated', enabled = false
        WHERE status <> 'deprecated'
          AND concept_id IN (SELECT child_concept_id FROM concept_parent
                             WHERE parent_concept_id = NEW.concept_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_cascade_concept_parent_deprecation(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_cascade_concept_parent_deprecation() IS 'L-9: generalizes feature_registry.fn_cascade_parent_deprecation() from a tier=''1_interaction''-filtered, parent_features-array-scanning original to a concept_parent-join-scoped trigger that fires across every domain automatically. Two deliberate generalizations over the original: (a) no tier filter -- scoping comes from the join table alone; (b) the inner UPDATE re-fires this same trigger per touched child, so multi-level chains (grandparent -> parent -> child) cascade with no extra code -- safe only because fn_concept_parent_cycle_guard() guarantees the graph has no cycles. Fixes two real bugs present in both the feature_registry original and todo 118''s proposed literal translation: BUG-1 (audit INSERT must run BEFORE the UPDATE, or it silently selects zero rows) and BUG-2 (from_status must be the child''s real current status, never a hard-coded literal).';


--
-- Name: fn_concept_parent_cycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_concept_parent_cycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        WITH RECURSIVE descendants(id) AS (
            SELECT NEW.child_concept_id
            UNION
            SELECT cp.child_concept_id
            FROM concept_parent cp JOIN descendants d ON cp.parent_concept_id = d.id
        )
        SELECT 1 FROM descendants WHERE id = NEW.parent_concept_id
    ) THEN
        RAISE EXCEPTION 'concept_parent cycle rejected: parent % is already a descendant of child %',
            NEW.parent_concept_id, NEW.child_concept_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_concept_parent_cycle_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_concept_parent_cycle_guard() IS 'Rejects any concept_parent INSERT or UPDATE that would make NEW.parent_concept_id a descendant of NEW.child_concept_id (a cycle). Exists because fn_cascade_concept_parent_deprecation'' is deliberately recursive across this same table, and that recursion is only safe if the lineage DAG has no cycles -- this guard makes acyclicity an enforced invariant, not an assumption. KNOWN CONCURRENCY LIMIT: the recursive check above reads only COMMITTED edges. Two concurrent transactions that each insert one leg of a two-edge cycle (A->B in one, B->A in the other) can therefore both pass and both commit -- neither sees the other''s uncommitted row. Closing that would require SERIALIZABLE isolation or a table-level advisory lock on every edge write. Neither is warranted in this phase: concept_parent''s ONLY writer is migration 284, which inserts all edges inside a single transaction, and no runtime service writes lineage edges. CONTRACT: any future component that writes concept_parent outside a single-transaction seed MUST take pg_advisory_xact_lock() on a fixed key covering this table first, or this guard is best-effort for that writer.';


--
-- Name: fn_research_run_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_research_run_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'started' THEN
            RAISE EXCEPTION 'research_run is append-only: a row must be inserted as started, got %',
                NEW.status
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.evidence IS NOT NULL OR NEW.finished_at IS NOT NULL
           OR NEW.snapshot_hash IS NOT NULL THEN
            RAISE EXCEPTION 'research_run is append-only: a started row carries no evidence, '
                'finished_at or snapshot_hash'
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;

    -- UPDATE
    IF OLD.status <> 'started' THEN
        RAISE EXCEPTION 'research_run is append-only: run % is already terminal (%)',
            OLD.run_id, OLD.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status NOT IN ('completed', 'guard_failed', 'refused', 'failed') THEN
        RAISE EXCEPTION 'research_run is append-only: a started row may only move to a '
            'terminal status, got %', NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.finished_at IS NULL THEN
        RAISE EXCEPTION 'research_run is append-only: a terminal row needs finished_at'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.run_id IS DISTINCT FROM OLD.run_id
       OR NEW.run_group IS DISTINCT FROM OLD.run_group
       OR NEW.concept_id IS DISTINCT FROM OLD.concept_id
       OR NEW.kind IS DISTINCT FROM OLD.kind
       OR NEW.mode IS DISTINCT FROM OLD.mode
       OR NEW.spec_path IS DISTINCT FROM OLD.spec_path
       OR NEW.spec_hash IS DISTINCT FROM OLD.spec_hash
       OR NEW.spec_blob IS DISTINCT FROM OLD.spec_blob
       OR NEW.code_commit IS DISTINCT FROM OLD.code_commit
       OR NEW.vintage IS DISTINCT FROM OLD.vintage
       OR NEW.budget_m IS DISTINCT FROM OLD.budget_m
       OR NEW.screen_alpha IS DISTINCT FROM OLD.screen_alpha
       OR NEW.started_at IS DISTINCT FROM OLD.started_at THEN
        RAISE EXCEPTION 'research_run is append-only: only status, snapshot_hash, evidence and '
            'finished_at change, once'
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.snapshot_hash IS NOT NULL
       AND NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash THEN
        RAISE EXCEPTION 'research_run is append-only: snapshot_hash may go from NULL to a '
            'value, never change'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


