--
-- Name: recompress_signal_ledger(integer, jsonb); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.recompress_signal_ledger(IN job_id integer, IN config jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
  chunk_row record;
BEGIN
  FOR chunk_row IN
    SELECT chunk_schema, chunk_name
    FROM timescaledb_information.chunks
    WHERE hypertable_name = 'signal_ledger'
      AND is_compressed = true
      AND range_end < NOW() - INTERVAL '1 day'
  LOOP
    CALL recompress_chunk(format('%I.%I', chunk_row.chunk_schema, chunk_row.chunk_name)::regclass);
  END LOOP;
END;
$$;


--
-- Name: update_signal_ledger_derived_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_signal_ledger_derived_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.effective_ts := COALESCE(NEW.signal_computed_at, NEW.feature_ts);

  IF NEW.signal_computed_at IS NOT NULL AND NEW.feature_ts IS NOT NULL THEN
    NEW.pipeline_lag_ms := EXTRACT(EPOCH FROM (NEW.signal_computed_at - NEW.feature_ts)) * 1000.0;
  ELSE
    NEW.pipeline_lag_ms := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: weekly_db_maintenance(integer, jsonb); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.weekly_db_maintenance(IN job_id integer, IN config jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Refresh materialized views
  REFRESH MATERIALIZED VIEW CONCURRENTLY signal_stats_daily;

  -- Update planner statistics on all key tables
  ANALYZE intelligence_features;
  ANALYZE signal_ledger;
  ANALYZE llm_calls;
  ANALYZE market_data_ohlcv;
  ANALYZE signal_features;
  ANALYZE drift_monitor;
  ANALYZE signal_performance_segmented;
  ANALYZE setup_performance;

  -- Reset slow query stats for a fresh weekly window
  PERFORM pg_stat_statements_reset();

  RAISE NOTICE 'Weekly maintenance complete at %', now();
END;
$$;


