--
-- Name: forward_returns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.forward_returns (
    symbol text NOT NULL,
    tf text NOT NULL,
    bar_ts timestamp with time zone NOT NULL,
    pipeline_version text NOT NULL,
    regime_label_source text DEFAULT 'forward_filter'::text NOT NULL,
    return_fast double precision,
    return_mid double precision,
    return_slow double precision,
    return_extended double precision,
    complete_fast boolean DEFAULT false CONSTRAINT forward_returns_complete_1bar_not_null NOT NULL,
    complete_mid boolean DEFAULT false CONSTRAINT forward_returns_complete_5bar_not_null NOT NULL,
    complete_slow boolean DEFAULT false CONSTRAINT forward_returns_complete_20bar_not_null NOT NULL,
    complete_extended boolean DEFAULT false CONSTRAINT forward_returns_complete_60bar_not_null NOT NULL,
    has_gap_before_entry boolean DEFAULT false NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    forward_return_id uuid,
    return_type text DEFAULT 'executable_open_to_open'::text NOT NULL,
    return_fast_suspect boolean DEFAULT false NOT NULL,
    return_mid_suspect boolean DEFAULT false NOT NULL,
    return_slow_suspect boolean DEFAULT false NOT NULL,
    return_extended_suspect boolean DEFAULT false NOT NULL,
    CONSTRAINT forward_returns_return_type_check CHECK ((return_type = ANY (ARRAY['executable_open_to_open'::text, 'theoretical'::text])))
);


--
-- Name: COLUMN forward_returns.forward_return_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.forward_returns.forward_return_id IS 'SHA-256(symbol|tf|bar_ts_ns|pipeline_version)[:32] as UUID. Content-addressed row key.
     Idempotent across replays. NULL for rows written before migration 166.
     Uniqueness guaranteed at application layer (SHA-256 collision resistance).
     Mirrors feature_vector_id on feature_vectors (migration 158).';


--
-- Name: COLUMN forward_returns.return_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.forward_returns.return_type IS 'Return computation type: executable_open_to_open (ln(open[T+N+1]/open[T+1])) or theoretical (ln(close[T+N]/close[T])). IC engine MUST filter for executable_open_to_open.';


