--
-- Name: alpha_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.alpha_events (
    event_id text NOT NULL,
    symbol text NOT NULL,
    tf text NOT NULL,
    bar_ts timestamp with time zone NOT NULL,
    ensemble_version text NOT NULL,
    weight_version text NOT NULL,
    regime text,
    alpha_score double precision NOT NULL,
    alpha_ci_lower double precision,
    alpha_ci_upper double precision,
    effective_n double precision,
    n_features_active integer,
    emission_threshold double precision,
    direction text NOT NULL,
    top_features jsonb NOT NULL,
    emitted_at timestamp with time zone DEFAULT now() NOT NULL,
    cost_hurdle double precision DEFAULT 0.0 NOT NULL,
    is_shadow boolean DEFAULT true NOT NULL,
    CONSTRAINT alpha_events_direction_check CHECK ((direction = ANY (ARRAY['long'::text, 'short'::text])))
);


--
-- Name: COLUMN alpha_events.cost_hurdle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.alpha_events.cost_hurdle IS 'Cost hurdle value (alpha_score units) that was in effect when this event was emitted. Records the APR value at publish time for audit trail. Zero = no cost gate applied.';


