);


--
-- Name: alpha_frames; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.alpha_frames (
    frame_id text NOT NULL,
    event_id text NOT NULL,
    bar_ts timestamp with time zone NOT NULL,
    symbol text NOT NULL,
    tf text NOT NULL,
    regime text,
    direction text NOT NULL,
    frame_variant text DEFAULT 'primary'::text NOT NULL,
    alpha_score double precision NOT NULL,
    alpha_ci_lower double precision,
    alpha_ci_upper double precision,
    gross_expected_r double precision,
    net_expected_r double precision,
    cost_r double precision,
    entry_price double precision,
    stop_price double precision,
    target_price double precision,
    r_multiple double precision,
    max_hold_bars integer,
    stop_atr_mult double precision,
    status text DEFAULT 'open'::text NOT NULL,
    counterfactual_pnl_r double precision,
    counterfactual_mfe double precision,
    counterfactual_mae double precision,
    counterfactual_bars integer,
    exit_reason text,
    closed_at timestamp with time zone,
    measured_at timestamp with time zone,
    corpus_run_id text,
    weight_epoch text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    target_r_multiple double precision,
    is_shadow boolean DEFAULT true NOT NULL,
    CONSTRAINT alpha_frames_direction_check CHECK ((direction = ANY (ARRAY['long'::text, 'short'::text]))),
    CONSTRAINT alpha_frames_status_check CHECK ((status = ANY (ARRAY['open'::text, 'closed_stop'::text, 'closed_target'::text, 'closed_max_hold'::text, 'closed_ic_decay'::text])))
);


--
-- Name: COLUMN alpha_frames.gross_expected_r; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.alpha_frames.gross_expected_r IS 'D-03 diagnostic snapshot, NOT a gate input. Ex-ante expected payoff MAGNITUDE in R at frame-entry time: abs(alpha_score) * alpha.frame.target_r_multiple. alpha_score is an IC-weighted ensemble score, not a probability; this is a directional-confidence magnitude scaled by the frame''s design R-multiple on a win, not a realized or expected P&L. Direction-agnostic (abs value) -- the traded direction is already fixed by the direction column. Reporting-only; SHADOW-REVIEW.md gates on realized counterfactual_pnl_r, never on this column.';


--
-- Name: COLUMN alpha_frames.net_expected_r; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.alpha_frames.net_expected_r IS 'D-03 diagnostic snapshot, NOT a gate input (D-01: SHADOW-REVIEW.md gates on GROSS counterfactual_pnl_r only). gross_expected_r - cost_r. D-02: reported as a mandatory REPORTING-ONLY column alongside every gross metric SHADOW-REVIEW.md commits to.';


--
-- Name: COLUMN alpha_frames.cost_r; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.alpha_frames.cost_r IS 'D-03 diagnostic snapshot. Per-row cost hurdle in return space, copied through from alpha_events.cost_hurdle (the audit snapshot alpha_publisher.py stamps at publish time via _cost_hurdle_for_tf) -- NOT re-derived live from the alpha.quant.cost_hurdle.<tf> APR key, so net_expected_r never silently drifts from historical truth on the next cost-hurdle recalibration + backfill re-run.';


--
-- Name: COLUMN alpha_frames.target_r_multiple; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.alpha_frames.target_r_multiple IS 'APR snapshot at creation: alpha.frame.target_r_multiple. Mirrors stop_atr_mult -- read back unchanged by CounterfactualTracker instead of re-deriving live from APR at scan time, so target_price/r_multiple/counterfactual_pnl_r never silently desync from the gross_expected_r/net_expected_r diagnostics computed at frame-creation time under this same value (Phase 142B code-review CR-02).';


