--
-- Name: classification_node; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.classification_node (
    scheme text NOT NULL,
    code text NOT NULL,
    parent_code text,
    level smallint NOT NULL,
    name text NOT NULL,
    path text[] NOT NULL,
    valid_from date NOT NULL,
    valid_to date,
    CONSTRAINT classification_node_check CHECK (((parent_code IS NULL) = (level = 1))),
    CONSTRAINT classification_node_check1 CHECK (((cardinality(path) = level) AND (path[cardinality(path)] = code))),
    CONSTRAINT classification_node_check2 CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT classification_node_level_check CHECK ((level >= 1))
);


--
-- Name: TABLE classification_node; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.classification_node IS 'Reference data, migration-seeded. One row per node in a classification tree (scheme, code) -- append-only in effect: parent_code and level are immutable per (scheme, code); a reparent mints a new code, never an UPDATE of an existing row''s parent or level (node-immutability invariant, D-01). name may update in place (display metadata only, no consumer keys on historical node names).';


--
-- Name: classification_scheme; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.classification_scheme (
    scheme text NOT NULL,
    name text NOT NULL,
    authority text NOT NULL,
    source_ref text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT classification_scheme_scheme_check CHECK ((scheme ~ '^[a-z0-9_]+$'::text))
);


--
-- Name: TABLE classification_scheme; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.classification_scheme IS 'Reference data, migration-seeded. One row per classification scheme (e.g. indicagent_v1 -- project-owned, not GICS; GICS assignments are licensed data and this scheme only reuses public GICS sector/industry-group names, per D-03).';


--
-- Name: concept_annotation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.concept_annotation (
    annotation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    concept_id uuid NOT NULL,
    annotation_type text NOT NULL,
    content text NOT NULL,
    source text NOT NULL,
    confidence double precision,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT concept_annotation_annotation_type_check CHECK ((annotation_type = ANY (ARRAY['thesis'::text, 'assumption'::text, 'failure_mode'::text, 'observation'::text, 'open_question'::text, 'implementation'::text, 'reference'::text]))),
    CONSTRAINT concept_annotation_confidence_check CHECK (((confidence >= (0)::double precision) AND (confidence <= (1)::double precision))),
    CONSTRAINT concept_annotation_source_check CHECK ((source = ANY (ARRAY['human'::text, 'ai'::text, 'empirical'::text])))
);


--
-- Name: TABLE concept_annotation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.concept_annotation IS 'Typed knowledge layer. The gate proves, the annotation explains - never invert: no gate decision may read annotation content, and no promotion may require an annotation to exist. source=empirical covers durable loss/win trail rows appended by plan 160-03, distinct from human-authored thesis/assumption content and any future ai-authored annotation.';


--
-- Name: concept_evaluation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.concept_evaluation (
    concept_id uuid NOT NULL,
    domain text NOT NULL,
    window_end timestamp with time zone NOT NULL,
    evidence_key text NOT NULL,
    evaluated_status text NOT NULL,
    passed boolean NOT NULL,
    statistic double precision,
    n_cells integer NOT NULL,
    n_observations bigint NOT NULL,
    guard_status text NOT NULL,
    detail jsonb,
    evaluated_at timestamp with time zone DEFAULT now() NOT NULL,
    run_ref text,
    CONSTRAINT concept_evaluation_domain_check CHECK ((domain = ANY (ARRAY['feature'::text, 'ensemble_strategy'::text, 'construction'::text]))),
    CONSTRAINT concept_evaluation_evaluated_status_check CHECK ((evaluated_status = ANY (ARRAY['candidate'::text, 'shadow_only'::text, 'active'::text, 'deprecated'::text]))),
    CONSTRAINT concept_evaluation_guard_status_check CHECK ((guard_status = ANY (ARRAY['ok'::text, 'hold_high'::text, 'alert_low'::text, 'insufficient_cells'::text, 'uncalibrated'::text])))
);


--
-- Name: TABLE concept_evaluation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.concept_evaluation IS 'Append-only lifecycle evidence ledger (todo 402, migration 357). Status is derived from the latest row per (concept, window_end); see services/feature_lifecycle.py.';


--
-- Name: concept_gate; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.concept_gate (
    concept_id uuid NOT NULL,
    gate_metric_name text NOT NULL,
    gate_eval_method text NOT NULL,
    min_gate_metric double precision,
    min_gate_n double precision,
    min_promotion_consecutive integer,
    min_new_observations double precision,
    demotion_threshold double precision,
    decay_floor double precision,
    regime_scope text,
    fdr_required boolean DEFAULT false NOT NULL,
    fdr_alpha double precision,
    last_eval_metric double precision,
    last_eval_n double precision,
    last_eval_at timestamp with time zone,
    last_eval_corpus_build_ref text,
    baseline_metric double precision,
    decay_ratio double precision,
    promotion_consecutive integer DEFAULT 0 NOT NULL,
    promotion_eval_metrics double precision[] DEFAULT '{}'::double precision[] NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    consecutive_shadow_passes integer DEFAULT 0 NOT NULL,
    observations_since_demotion bigint DEFAULT 0 NOT NULL,
    consecutive_active_fails integer DEFAULT 0 NOT NULL,
    min_demotion_consecutive integer,
    CONSTRAINT concept_gate_gate_eval_method_check CHECK ((gate_eval_method = ANY (ARRAY['oos_holdout'::text, 'walk_forward'::text, 'bootstrap_ci'::text])))
);


--
-- Name: TABLE concept_gate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.concept_gate IS 'Per-concept promotion/demotion gate PLUS folded last-eval cache (MVP merges concept_eval_state here, mirroring feature_registry). min_gate_n and min_new_observations are EFFECTIVE-N floors (invariant 7): overlapping forward returns are autocorrelated, so raw bar counts never satisfy them. NULL gate columns inherit the per-domain APR default (alpha.concept_registry.<domain>_* keys). baseline_metric stores the MEAN of promotion_eval_metrics at promotion (F8 winner''s-curse guard), never the final eval alone.';


--
-- Name: COLUMN concept_gate.fdr_required; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.concept_gate.fdr_required IS 'Advisory only. ConceptRegistryService does NOT read this column - BH-FDR enforcement lives entirely upstream in scripts/ops/alpha/ops_ensemble_weight_compare.py. This flag documents intent for a given concept''s gate; it does not itself enforce anything.';


--
-- Name: COLUMN concept_gate.consecutive_shadow_passes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.concept_gate.consecutive_shadow_passes IS 'L-5: ported from feature_registry.consecutive_shadow_passes (migration 209, Phase 143 LIFECYCLE-01). Compared against the EXISTING alpha.decay.recovery_min_passes APR key (no new key minted) for shadow_only -> active promotion eligibility.';


--
-- Name: COLUMN concept_gate.observations_since_demotion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.concept_gate.observations_since_demotion IS 'L-5: ported from feature_registry.observations_since_demotion (migration 209, Phase 143 LIFECYCLE-01). Compared against the EXISTING alpha.decay.recovery_min_observations APR key (no new key minted) for shadow_only -> active promotion eligibility.';


--
-- Name: COLUMN concept_gate.consecutive_active_fails; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.concept_gate.consecutive_active_fails IS 'Todo 323: consecutive corpus runs (for an active concept) where the cross-sectional materiality check failed (demote_fraction >= demotion_fraction_floor). Incremented by ConceptRegistryService.advance_active_counters_sync on a failing run, reset to 0 on a passing run AND on any transition into active (a freshly (re)promoted concept must not inherit a stale fail-streak from before its last demotion). Demotion only fires once this crosses min_demotion_consecutive.';


--
-- Name: COLUMN concept_gate.min_demotion_consecutive; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.concept_gate.min_demotion_consecutive IS '[initial_estimate] Todo 323: per-concept override of the APR default (alpha.decay.demotion_min_consecutive) -- NULL (the seeded value for every existing row) means "use the caller-resolved APR default", matching min_promotion_consecutive''s existing override convention exactly. Candidate ML learning target once enough demotion history accumulates to tune it empirically.';


--
-- Name: concept_parent; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.concept_parent (
    child_concept_id uuid NOT NULL,
    parent_concept_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT concept_parent_no_self_check CHECK ((child_concept_id <> parent_concept_id))
);


--
-- Name: TABLE concept_parent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.concept_parent IS 'Multi-parent lineage join table (L-8), superseding feature_registry.parent_features'' bare TEXT[] of feature names with real FK-enforced referential integrity on both child_concept_id and parent_concept_id. concept_registry.parent_concept_id (single-parent FK column) is NOT dropped -- domain=''ensemble_strategy'' may still reference it; the feature domain uses this table exclusively. Deliberately carries NO ordinality column: no consumer of lineage depends on parent order (Plan 07 traces the single reader end to end and proves it with an invariance test). If a future consumer ever needs order, the fix is an explicit ordinality column seeded from unnest(...) WITH ORDINALITY, not an implicit reliance on insertion order.';


--
-- Name: concept_registry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.concept_registry (
    concept_id uuid DEFAULT gen_random_uuid() NOT NULL,
    domain text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    status text DEFAULT 'candidate'::text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    parent_concept_id uuid,
    redundancy_group text,
    metadata jsonb,
    added_phase text,
    sensitivity text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    is_control boolean DEFAULT false NOT NULL,
    control_expectation text,
    group_name text,
    CONSTRAINT concept_registry_control_expectation_check CHECK (((control_expectation IS NULL) OR (control_expectation = ANY (ARRAY['negative_control'::text, 'positive_control'::text])))),
    CONSTRAINT concept_registry_domain_check CHECK ((domain = ANY (ARRAY['feature'::text, 'ensemble_strategy'::text, 'construction'::text]))),
    CONSTRAINT concept_registry_status_check CHECK ((status = ANY (ARRAY['candidate'::text, 'shadow_only'::text, 'active'::text, 'deprecated'::text])))
);


--
-- Name: TABLE concept_registry; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.concept_registry IS 'Unified Concept Registry (Type 2 lifecycle governance) - identity and current status per research recipe. status = recipe validity; per-stratum deployment stays a fact in domain fact tables (F2 resolution: ensemble_weights holds per-stratum champions, not this table). redundancy_group displacement is DISABLED for domain=ensemble_strategy (competing weighting strategies are the normal state, resolved per stratum by the A/B judge).';


--
-- Name: COLUMN concept_registry.is_control; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.concept_registry.is_control IS 'L-10: ported from feature_registry.is_control (5 rows true today). Marks a concept as a control canary (positive or negative) rather than a real candidate signal.';


--
-- Name: COLUMN concept_registry.control_expectation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.concept_registry.control_expectation IS 'L-10: ported from feature_registry.control_expectation. Live values today: negative_control, positive_control. CHECK-free in feature_registry; constrained here to those two known values via concept_registry_control_expectation_check.';


--
-- Name: COLUMN concept_registry.group_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.concept_registry.group_name IS 'L-10: ported from feature_registry.group_name. Deliberately UNCONSTRAINED TEXT (no CHECK like feature_registry''s 11-value list) -- the vocabulary is domain-specific and concept_registry is cross-domain; the controlled-vocabulary system (vocabulary_drift.py, Phase 161) polices its values, not a table CHECK. NOT decorative: read with real SQL-level filtering by ops_ic_shrinkage.py (leave-one-out peer-group shrinkage), ops_ensemble_ablation.py (SELECT DISTINCT group_name), and ops_broadcast_feature_audit.py -- given a dedicated column for the same reason is_control is (both scripts do real WHERE filtering today; JSONB predicates would be a pure regression for no benefit).';


