--

CREATE TABLE public.dividend_events (
    symbol text NOT NULL,
    ex_date date NOT NULL,
    source text NOT NULL,
    amount double precision NOT NULL,
    prev_close double precision NOT NULL,
    compute_version text NOT NULL,
    derived_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dividend_events_amount_check CHECK ((amount > (0)::double precision)),
    CONSTRAINT dividend_events_finite CHECK (((amount <> 'NaN'::double precision) AND (amount <> 'Infinity'::double precision) AND (prev_close <> 'NaN'::double precision) AND (prev_close <> 'Infinity'::double precision))),
    CONSTRAINT dividend_events_prev_close_check CHECK ((prev_close > (0)::double precision)),
    CONSTRAINT dividend_events_source_check CHECK ((source = ANY (ARRAY['yahoo'::text, 'ibkr_adjusted_last_ratio'::text])))
);


--
-- Name: TABLE dividend_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.dividend_events IS 'Per-share cash distributions by ex-date and source (todo 428). Read amount / prev_close (the yield on the ex-date): both are in the split units of the day the row was derived. First derivation wins; re-derivations never overwrite. Readers use dividend_events_reconciled, not this table.';


--
-- Name: dividend_events_reconciled; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dividend_events_reconciled AS
 SELECT symbol,
    ex_date,
    max((amount / prev_close)) FILTER (WHERE (source = 'yahoo'::text)) AS yahoo_yield,
    max((amount / prev_close)) FILTER (WHERE (source = 'ibkr_adjusted_last_ratio'::text)) AS ibkr_yield,
    COALESCE(max((amount / prev_close)) FILTER (WHERE (source = 'yahoo'::text)), max((amount / prev_close)) FILTER (WHERE (source = 'ibkr_adjusted_last_ratio'::text))) AS dividend_yield,
    max(prev_close) FILTER (WHERE (source = 'ibkr_adjusted_last_ratio'::text)) AS ibkr_prev_close
   FROM public.dividend_events
  GROUP BY symbol, ex_date;


--
-- Name: VIEW dividend_events_reconciled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.dividend_events_reconciled IS 'One row per (symbol, ex_date): each source''s yield (NULL where it lacks the event), IBKR''s prior close (for its rounding bound, 0.02 / close) and dividend_yield, a naive Yahoo-first default. Facts only: research readers resolve agreement, dispute and single-source events with research/dividends.resolve_event, not dividend_yield (todo 428).';


