    ic_win_rate,
    sign_hit_rate,
    magnitude_conditional_ic,
    ic_ci_lower,
    ic_ci_upper,
    p_value,
    bh_adjusted_p,
    passes_ci_gate,
    passes_fdr,
    wf_fold_count,
    wf_pass_count,
    wf_ic_sharpe,
    passes_walkforward,
