    CONSTRAINT chk_transition_probs_sum CHECK (((transition_probs IS NULL) OR (abs((((((transition_probs ->> 'ranging'::text))::double precision + ((transition_probs ->> 'trending_up'::text))::double precision) + ((transition_probs ->> 'trending_down'::text))::double precision) - (1.0)::double precision)) < (0.001)::double precision))),
