    route text NOT NULL,
    what_to_show text NOT NULL,
    fetched_at timestamp with time zone NOT NULL,
    CONSTRAINT ohlcv_observation_finite CHECK (((open <> 'NaN'::double precision) AND (open <> 'Infinity'::double precision) AND (open <> '-Infinity'::double precision) AND (high <> 'NaN'::double precision) AND (high <> 'Infinity'::double precision) AND (high <> '-Infinity'::double precision) AND (low <> 'NaN'::double precision) AND (low <> 'Infinity'::double precision) AND (low <> '-Infinity'::double precision) AND (close <> 'NaN'::double precision) AND (close <> 'Infinity'::double precision) AND (close <> '-Infinity'::double precision))),
    CONSTRAINT ohlcv_observation_timeframe_check CHECK ((timeframe = '1d'::text))
);


