--

CREATE TABLE public.ohlcv_request (
    request_id uuid NOT NULL,
    fetch_run_id uuid NOT NULL,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    source text NOT NULL,
    route text NOT NULL,
    what_to_show text NOT NULL,
