    CONSTRAINT ohlcv_request_n_bars_check CHECK ((n_bars >= 0)),
    CONSTRAINT ohlcv_request_outcome_check CHECK ((outcome = ANY (ARRAY['bars'::text, 'no_data'::text, 'timeout'::text, 'failed'::text, 'legacy_import'::text]))),
    CONSTRAINT ohlcv_request_route_check CHECK ((route ~ '^[A-Z_]{2,16}$'::text)),
    CONSTRAINT ohlcv_request_source_check CHECK ((source = 'ibkr'::text)),
    CONSTRAINT ohlcv_request_what_to_show_check CHECK ((what_to_show = ANY (ARRAY['TRADES'::text, 'ADJUSTED_LAST'::text])))
);


