--

COMMENT ON TABLE public.ohlcv_request IS 'Append-only log of every IBKR history request and its outcome (migration 380, D1). One row per request, any timeframe; request_id is generated by the provider. TRADES and ADJUSTED_LAST pair only within one fetch_run_id. Permanent: UPDATE, DELETE and TRUNCATE raise.';


--
-- Name: ohlcv_venue_head; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ohlcv_venue_head AS
 WITH smart_head AS (
         SELECT ohlcv_observation.symbol,
            min(ohlcv_observation.bar_date) AS smart_head_date
           FROM public.ohlcv_observation
          WHERE ((ohlcv_observation.route = 'SMART'::text) AND (ohlcv_observation.what_to_show = 'TRADES'::text))
          GROUP BY ohlcv_observation.symbol
        )
 SELECT o.symbol,
    o.route,
    min(o.bar_date) AS first_bar_date,
    max(o.bar_date) AS last_bar_date,
    count(*) AS n_bars,
    sh.smart_head_date,
    ((max(o.bar_date) < sh.smart_head_date) OR (sh.smart_head_date IS NULL)) AS pre_move
   FROM (public.ohlcv_observation o
     LEFT JOIN smart_head sh ON ((sh.symbol = o.symbol)))
  WHERE ((o.route <> 'SMART'::text) AND (o.route <> 'LEGACY_IMPORT'::text) AND (o.what_to_show = 'TRADES'::text))
  GROUP BY o.symbol, o.route, sh.smart_head_date;


--
-- Name: VIEW ohlcv_venue_head; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.ohlcv_venue_head IS 'Per (symbol, non-SMART route): first and last TRADES 1d bar date, observation count, the symbol''s SMART TRADES head date (NULL if none), and pre_move = the route ends before the SMART head or there is no SMART head. The moved-name inventory (D-20 evidence, D-25 input).';


