--
-- Name: signal_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.signal_ledger AS
 SELECT se.signal_id,
    se.ts,
    se.ts AS "timestamp",
    se.symbol,
    se.tf,
    se.tf AS timeframe,
    se.setup_plugin,
    se.direction,
    se.raw_confidence,
    se.calibrated_confidence,
    se.cis_score,
    se.factor_scores,
    se.context_features,
    se.ctf_score,
    se.ctf_confirmed,
    se.zone_friction_score,
    se.hmm_regime_at_fire,
    se.plugin_regime_type,
    se.garch_sigma_at_fire,
    se.is_shadow,
    se.is_backfill,
    se.status,
    se.signal_schema_version,
    se.ttl_bars,
    se.expires_at,
    COALESCE(se.signal_computed_at, se.ts) AS signal_computed_at,
    se.signal_computed_at AS signal_computed_at_raw,
    se.feature_ts,
    se.concurrent_signal_count,
    se.concurrent_plugins,
    ((tf.frame_details ->> 'activated_at'::text))::timestamp with time zone AS activated_at,
    ((tf.frame_details ->> 'activation_price'::text))::double precision AS activation_price,
    tf.targets,
    ((tf.frame_details ->> 'entry_zone_low'::text))::double precision AS entry_zone_low,
    ((tf.frame_details ->> 'entry_zone_high'::text))::double precision AS entry_zone_high,
    ((tf.frame_details ->> 'market_entry_price'::text))::double precision AS market_entry_price,
    ((tf.frame_details ->> 'trailing_stop_price'::text))::double precision AS trailing_stop_price,
    (tf.frame_details ->> 'chandelier_vol_source'::text) AS chandelier_vol_source,
    ((tf.frame_details ->> 'mae'::text))::double precision AS mae,
    ((tf.frame_details ->> 'mfe'::text))::double precision AS mfe,
    tf.frame_id,
    tf.entry_type,
    tf.entry_price,
    tf.stop_price,
    tf.stop_price AS stop_loss,
    tf.target_price,
    tf.r_multiple,
    tf.counterfactual_pnl_r,
    tf.counterfactual_mfe,
    tf.counterfactual_mae,
    tf.counterfactual_exit_reason,
    tf.was_selected,
    tf.regime_at_activation,
    te.execution_id,
    te.actual_pnl_r,
    te.actual_fill_price,
    te.actual_exit_price,
    te.exit_reason,
    te.executed_at,
    te.exited_at,
    te.exited_at AS exit_at,
    te.regime_at_exit
   FROM ((public.signal_events se
     LEFT JOIN public.trade_frames tf ON (((tf.signal_id = se.signal_id) AND (tf.signal_ts = se.ts))))
     LEFT JOIN public.trade_executions te ON ((te.frame_id = tf.frame_id)));


